# Function to perform the first type operation (Reverse array A)
def reverse_array(A):
    return A[::-1]

# Function to perform the second type operation (Floyd-Warshall algorithm)
# Considering array length up to 2*10^5
def find_shortest_paths(A, n):
    graph = [[(float("inf"), 0) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                graph[i][j] = (0, 0)  # Distance and number of operations
    for i in range(n):
        A[i] -= i  # Convert to 1-based for Floyd-Warshall
    for k in range(n):
        for i in range(n):
            for j in range(n):
                graph[i][j] = min(graph[i][j], (graph[i][k][0] + graph[k][j][0] - A[k] - A[j], graph[i][k][1] + graph[k][j][1] - 1))
    return graph

def solve(A, B, n):
    # Copy A for Floyd-Warshall
    for i in range(n):
        A[i] -= i

    # Initialize variables
    paths = find_shortest_paths(A, n)
    operations = deque()
    total_operations = 0

    # Optimization for Floyd-Warshall similar to the editorial explanation
    while not all(min(graph[0]) == (0, 0) for graph in paths):
        for i in range(n):
            for j in range(n):
                graph = paths[i][i][n-2-i]
                if graph != (0, 0) and graph[0] == 0:
                    ops = graph[1]
                    ops += 2
                    paths[i] = graph = (ops[0], ops[1] - 1)
                    paths[n-1-j] = ops = (ops[0], ops[1] - 1)
                    ops += 2
                    operations.append((i, j, ops))
                    break
            else:
                continue
            break
        else:
            continue
        break
    else:
        return "IMPOSSIBLE"

    num_ops = len(operations)
    if num_ops > 2 * 10**5:
        return "BIG\n" + str(num_ops - 1)

    first_type_ops = 0
    second_type_ops = 0
    for i, j, ops in operations:
        if ops[1] == 0:
            first_type_ops += 1
        elif ops[1] % 2 == 0 and len(operations) < 5 * 10**5:
            first_type_ops += 1
            second_type_ops += (ops[1] // 2)
        elif ops[1] % 2 == 0 and len(operations) >= 5 * 10**5:
            second_type_ops += (ops[1] // 2)
            return "SMALL\n" + " ".join(map(str, reversed(list("R" * i + j + "P" * ops[1] + "R"))))
    return "SMALL\n" + " ".join(map(str, reversed(list("R" * first_type_ops + "P" * second_type_ops))))

