            def rearrange_rows(r):
                if r[i-1] < r[i+1] and r[i+1] > r[i-2]:
                    left, right = sorted([r[i-1], r[i-1]])
                    for k in range(i - 1, i + 2):
                        r[k] = left if k < i else right
                    return r
            matrix[i] = rearrange_rows(matrix[i])

            # Define bitonic rearrangement function for columns
            def rearrange_columns(c):
                if c[j-1] < c[j+1] and c[j+1] > c[j-2]:
                    left, right = sorted([c[j-1], c[j-1]])
                    for k in range(j - 1, j + 2):
