from math import factorial as f

def multinomial_coefficient(n, r):
    return f(n) // (f(r) * f(n - r))

def count_groups(n, k, d):
    dp = [0] * (k + 1)
    dp[0] = 1  # Base case: 0 imbalance is possible with 1 student
    for i in range(n):
        next_dp = [0] * (k + 1)
        for m in range(k + 1):
            for d in range(2, k + 1):
                if m - d < 0:
                    break
                if dp[m - d] > 0:
                    w = max(d - 1, 1) * (-n // d + 1) + (n // d) * (-m // d + 1)
                    if w == 1:  
                        next_dp[-d] += dp[m]
                    elif w == k:
                        next_dp[-d + k] += dp[m]
                    elif m < k and m >= k - d: 
                        r = min(m + d - k, k) 
                        next_dp[r] += dp[m]
        dp = next_dp
    return dp[k]

def total_combinations(n, k):
    return multinomial_coefficient(n, n) // (f(k) * f(n - k))

def count_unbalanced_group(sans):
    groups = 0
    denom = (f(n) // f(n - len(sans))) % 1000000007
    s = 0
    seen = set()
    for i in range(n):
        if i not in seen:
            cur = f(n - i // len(sans) - 1) // (f(len(sans) - s) * f(n - i - len(sans) - 1))
            groups += (denom * cur) % 1000000007
            seen.add(i)
            s = max(s, min(i + len(sans) // len(s), len(sans)))
    return groups % 1000000007

def generate_permutations(k, n):
    m = 1256
    rev = [0] * n
    for i in range(n - 1, -1, -1):
        rev[i] = k % m
        k //= m
    ans = []
    while n:
        tmp = rev.pop()
        ans.append(tmp)
        n -= 1
    return ans
