def heapify(arr):
    h = []
    for i in range(len(arr)):
        if arr[0] > arr[i]:
            heappush(h, [arr[i], i])
    return h

def extract_max(arr):
    if not arr:
        return -1, -1
    val, index = heappop(arr)
    heappush(arr, [val, index])
    return val, index

def solve(m, n, rules):
    heap = []
    for i in range(m):
        id = i + 1
        count = 1
        diamonds = []
        for r in rules:
            if id in r:
                count, diamond = r[id]
                heappush(diamonds, 1 - diamond)  # -1 for a diamond case
                continue
            head_id, target = r[id]
            if id == target:
                continue
            while target > id:
                count, diamond = rules[target]
                heappush(diamonds, diamond)
                target -= 1
            if target > 0 and rules[target][0] > 0:
                heappush(diamonds, rules[target][1])
                continue
            heappush(diamonds, 1 - count)  # -2 for a blank giant case
        while diamonds:
            max_ = heappop(diamonds)
            if max_ == 1:
                count += 1
            else:
                if max_ > 1:
                    count += 1
                if max_ > -1:
                    count -= 1
        count = max(count, 1)
        heappush(heap, [count, id])
    return heap

