    dp = [[0] * 4 for _ in range(T + 1)]

    for t in range(1, T + 1):
        dp[t][1] = dp[t][2] = dp[t][3] = 1

    for genre in range(1, 4):
        for t in range(2, T + 1):
            # Skip transitions where genres are the same
            for g in range(1, 4):
                if genre != g:
                    dp[t][t % 2] += dp[t - t % 2][g % 2]

    return sum(dp[T]) % mod

