                dp[i][j | (1 << (n - i))], dp[i][j] = min(dp[i][j], combinations_count(dp[i - 1][j | (1 << (n - i))], (dp[i - 1][j] + dp[i][j]) % (10**9 + 7))), ((1 << i) + group_amb_diff)

