from typing import List

def find_bitonic_matrix(n: int, m: int, values: List[List[int]]) -> List[List[int]]:
    available_values = [i+1 for i in range(n*m)]
    maps = {}
    # Mapping each row and column index to the required value
    for r in range(n):
        for c in range(m):
            i = r*m+c
            maps[i] = values[r][c]
            available_values.remove(values[r][c])
    row_stamps = ['down', 'up'] * n
    col_stamps = ['left', 'right'] * m
    # Scrape the zeroes first
    for i in range(n):
        for j in range(m):
            vv = maps[i*m+j]
            if vv == 0:
                if row_stamps[i] == 'down':
                    row_stamps[i] = 'up'
                if col_stamps[j] == 'right':
                    col_stamps[j] = 'left'
                del maps[i*m+j]
                continue
            if row_stamps[i] == 'down':
                row_stamps[i] = 'up'
            for k in range(i+1, n):
                if row_stamps[k] == 'down':  # This means [i, i+1...n-1]
                    row_stamps[k] = 'up' # The "grids" are interchangeable so we want to go left-to-right about this "gcd"
                    if maps[(k-i)*m] == maps[i*m+(i+1)*m]:  # We favor going right-to-left on the "connected pieces" grid increasingly as long as values are identical
                        col_stamps = ['down']*(m-i-1)+['left']+['right']*(i-j-1)+['down']
                        maps[(k-i)*m] = col_stamps[-1]
                        break
    # Check the bits for both
    if col_stamps[0] == 'down' and col_stamps[m-1] == 'down':
        for i in range(m-1):
            if maps[i*m] != col_stamps[-1-i]:
                return [-1]
    if not all(row_stamps):
        return [-1]
    the_rows = [['0 0']*(m*n)]
    for i, rit in enumerate(row_stamps):
        for rit2 in ['up', 'down'] if rit == 'down' else ['down', 'up']:
            if rit2 == 'up':
                rearrange = sorted
            else:
                rearrange = lambda a : a[::-1]
            val_i = rearrange([maps[i*m+j] for j in range(m)])
            the_rows.append([f'{val_i[(i*m)+(k)%m]} {' '.join(map(str, val_i[(i*m):]))}'])
    for k, kv in enumerate([abbr+'1' for abbr in maps.keys()]):
        abbr2 = kv[k:] if kv[k] != 1 else kv + ['1'] + kv[:k]
        the_rows.append(f'{abbr} {' '.join(abbr2)}')
    return the_rows

