            sub2 |= sub1 & 0x0f

        elif code == "O":
            sub1 = sub2 & ((0x1f & b) << b)

            for i in range(4, 0, -1):
                carry = (sub1 >> i & 1)
                if carry:
                    sub1 ^= 0x0f

            indices.append(addr & 0x3)

            inconditionals.append(True)

            if b < 4:
                sub1 |= (b << 4)
            if a == 0 or a == b:
                sub1 += 15

            sub2 |= sub1 & 0x0f

        elif code == "X":
            sub1 = (sub2 & 0x0f)
            sub2 &= 0xff

            for i in range(4, 0, -1):
                carry = (sub1 >> i & 1)
                if carry:
                    sub1 ^= 0x0f

            indices.append(addr & 0x3)

            inconditionals.append(True)

            if a < 4:
                sub1 |= (a << 4)
            if b == 0 or b == a:
                sub1 += 15

            sub2 |= sub1 & 0x0f

        elif code == "a":
            if a >= 24:
                continue
            sub3 = sub4 & a << a
            sub4 |= sub3 & (0x1f & (0x1f >> 4 - a)) << a
            sub4 |= sub3 & (0x1f & (0x1f << a)) << a

            indices.append(addr & 0x3)

            inconditionals.append(False)

            sub2 |= 1

        elif code == "o":
            if b >= 24:
                continue
            sub1 = sub2 & 0xff
            sub2 |= 1
            sub3 = ((0x1f << 4 - a) ^ (1 << (b - 4)) - 0x11) & (-0x1f >> a) << a

            indices.append(addr & 0x3)

